?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Orders | LyaiDeu Admin</title><link rel="stylesheet" href="css/style.css"></head><body class="admin-body"><div class="admin-header"><h1 class="display" style="color:white;margin:0">📦 Order Management</h1><div class="admin-actions"><a href="admin.php" class="btn btn-outline">← Dashboard</a><a href="index.php" target="_blank" class="btn btn-outline">Website</a></div></div><div class="admin-container"><div class="admin-stats"><div><strong><?=count($orders)?></strong><span>Total Orders</span></div><?php foreach($counts as $k=>$v): ?><div><strong><?=$v?></strong><span><?=htmlspecialchars($k)?></span></div><?php endforeach; ?></div><?php if(isset($_GET['saved'])):?><div class="flash-banner flash-success">✅ Order status updated.</div><?php endif; ?><div class="admin-order-list"><?php if(!$orders): ?><div class="admin-card"><h3>No orders yet.</h3><p class="small-note">Orders placed by customers will appear here.</p></div><?php endif; ?><?php foreach($orders as $o): ?><article class="admin-order-card"><div class="order-card-head"><div><h2>#<?= (int)$o['id'] ?> · <?= htmlspecialchars($o['customer_name']) ?></h2><p><?= htmlspecialchars($o['created']) ?> · 📞 <?= htmlspecialchars($o['phone']) ?></p></div><form method="POST" class="status-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_admin'])?>"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><select name="status"><?php foreach(array_keys($counts) as $st): ?><option <?=$o['status']===$st?'selected':''?>><?=htmlspecialchars($st)?></option><?php endforeach; ?></select><button class="btn btn-primary" type="submit">Update</button></form></div><p>📍 <?=htmlspecialchars($o['address'])?><?php if($o['note']): ?> · 📝 <?=htmlspecialchars($o['note'])?><?php endif; ?></p><div class="admin-order-items"><?php foreach($o['items'] as $it): ?><span><?=htmlspecialchars($it['name'])?> × <?=$it['qty']?> — Rs. <?=$it['line_total']?></span><?php endforeach; ?></div><div class="summary-row total"><span>Total · <?=htmlspecialchars($o['payment'])?></span><strong>Rs. <?=$o['total']?></strong></div></article><?php endforeach; ?></div></div></body></html>